#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static size_t N = 40*1024*1024;
static unsigned char *pt, *ct;
static unsigned char key[32], nonce[12];
static int T;

static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}

void* worker(void* arg){
    long id = (long)arg;
    size_t chunk = N / T;
    size_t off = id * chunk;
    size_t sz = (id == T-1) ? (N - off) : chunk;
    unsigned char iv[16];
    memcpy(iv+4, nonce, 12);
    unsigned int ctr = 1 + off/64;
    iv[0]=ctr&0xff; iv[1]=(ctr>>8)&0xff; iv[2]=(ctr>>16)&0xff; iv[3]=(ctr>>24)&0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv);
    int outl=0;
    EVP_EncryptUpdate(ctx, ct+off, &outl, pt+off, sz);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main(int argc, char**argv){
    T = atoi(argv[1]);
    pt = malloc(N); ct = malloc(N);
    memset(key,0,32); memset(nonce,0,12);
    for(size_t i=0;i<N;i++) pt[i]=i&0xff;
    pthread_t th[T];
    // warmup
    for(long i=0;i<T;i++) pthread_create(&th[i],NULL,worker,(void*)i);
    for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    double a=now();
    for(long i=0;i<T;i++) pthread_create(&th[i],NULL,worker,(void*)i);
    for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    double b=now();
    printf("T=%d chacha20 40MB: %.4f s = %.2f GB/s\n", T, b-a, N/(b-a)/1e9);
    return 0;
}
EOF
