#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
int main(){
    unsigned char key[32], nonce[16];
    memset(key,0,32); memset(nonce,0,16);
    size_t sizes[] = {16384, 1<<20, 4<<20, 16<<20, 40<<20};
    for(int s=0;s<5;s++){
        size_t n = sizes[s];
        unsigned char *pt = malloc(n), *ct = malloc(n);
        for(size_t i=0;i<n;i++) pt[i]=i&0xff;
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, nonce);
        int outl=0;
        // warmup
        EVP_EncryptUpdate(ctx, ct, &outl, pt, n);
        double best=1e9;
        for(int it=0; it<20; it++){
            EVP_CIPHER_CTX *c2 = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(c2, EVP_chacha20(), NULL, key, nonce);
            double a=now();
            EVP_EncryptUpdate(c2, ct, &outl, pt, n);
