    for(int it=0; it<20; it++){
        double a=now();
        off=0; ctr=1;
        while(off<n){ chacha20_8blocks(ct+off, pt+off, key, nonce, ctr); off+=512; ctr+=8; }
        double b=now();
        if(b-a<best) best=b-a;
    }
    printf("AVX2 chacha20 40MB best: %.4f s = %.2f GB/s\n", best, n/best/1e9);
    return 0;
}
