#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
static size_t N; static unsigned char *a, *b; static int T;
void* worker(void* arg){
    long id=(long)arg; size_t chunk=N/T; size_t off=id*chunk; size_t sz=(id==T-1)?(N-off):chunk;
    __m256i *pa=(__m256i*)(a+off), *pb=(__m256i*)(b+off); size_t cnt=sz/32;
    for(size_t i=0;i<cnt;i++) pb[i]=pa[i];
    return NULL;
}
int main(int argc,char**argv){
    T=atoi(argv[1]); N=256*1024*1024;
    a=aligned_alloc(64,N); b=aligned_alloc(64,N);
    memset(a,1,N); memset(b,2,N);
    pthread_t th[T];
    for(long i=0;i<T;i++) pthread_create(&th[i],NULL,worker,(void*)i);
    for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    double t0=now();
    for(int it=0;it<8;it++){
        for(long i=0;i<T;i++) pthread_create(&th[i],NULL,worker,(void*)i);
        for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    }
    double t1=now();
    double bytes=8.0*N;
    printf("T=%d copy 256MB x8: %.4f s -> copy %.2f GB/s (r+w %.2f GB/s)\n", T, t1-t0, bytes/(t1-t0)/1e9, 2*bytes/(t1-t0)/1e9);
    return 0;
}
