{"command":"cd /var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/algotuneprobe_jvvzz35p/ep0; cat > fast.c <<'EOF'
#include <openssl/evp.h>
#include <openssl/core_names.h>
#include <openssl/params.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static int NTHREADS = 6;

typedef struct {
    const unsigned char *key;
    const unsigned char *nonce;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    uint32_t counter;
} chacha_job;

static void* chacha_worker(void *arg) {
    chacha_job *job = (chacha_job*)arg;
    unsigned char iv[16];
    uint32_t c = job->counter;
    iv[0] = c & 0xff; iv[1] = (c>>8)&0xff; iv[2]=(c>>16)&0xff; iv[3]=(c>>24)&0xff;
    memcpy(iv+4, job->nonce, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, job->key, iv);
    int outl = 0;
    EVP_EncryptUpdate(ctx, job->out, &outl, job->in, (int)job->len);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int solve(const unsigned char *key, const unsigned char *nonce,
          const unsigned char *plaintext, size_t ptlen,
          const unsigned char *aad, size_t aadlen,
          unsigned char *ciphertext, unsigned char *tag) {
    // 1. derive poly1305 key from chacha20 block 0 (counter=0)
    unsigned char block0[64];
    unsigned char zeros[64];
    memset(zeros, 0, 64);
    unsigned char iv0[16];
    memset(iv0, 0, 4);
    memcpy(iv0+4, nonce, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv0);
    int outl = 0;
    EVP_EncryptUpdate(ctx, block0, &outl, zeros, 64);
    EVP_CIPHER_CTX_free(ctx);
    unsigned char poly_key[32];
    memcpy(poly_key, block0, 32);

    // 2. parallel chacha20 encryption
    int T = NTHREADS;
    if (ptlen < (size_t)T * 64) T = 1;
    pthread_t threads[64];
    chacha_job jobs[64];
    size_t chunk = (ptlen / T) & ~(size_t)63;  // align to 64
    if (chunk == 0) chunk = 64;
    for (int i = 0; i < T; i++) {
        size_t off = (size_t)i * chunk;
        size_t len = (i == T-1) ? (ptlen - off) : chunk;
        jobs[i].key = key; jobs[i].nonce = nonce;
        jobs[i].in = plaintext + off; jobs[i].out = ciphertext + off;
        jobs[i].len = len;
        jobs[i].counter = 1 + (uint32_t)(off / 64);
        pthread_create(&threads[i], NULL, chacha_worker, &jobs[i]);
    }
    for (int i = 0; i < T; i++) pthread_join(threads[i], NULL);

    // 3. poly1305
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
    OSSL_PARAM params[2];
    params[0] = OSSL_PARAM_construct_utf8_string(OSSL_MAC_PARAM_DIGEST, "POLY1305", 0);
    params[1] = OSSL_PARAM_construct_end();
    EVP_MAC_init(mctx, poly_key, 32, params);
    unsigned char pad[16];
    memset(pad, 0, 16);
    EVP_MAC_update(mctx, aad, aadlen);
    size_t padlen = (16 - (aadlen % 16)) % 16;
    if (padlen) EVP_MAC_update(mctx, pad, padlen);
    EVP_MAC_update(mctx, ciphertext, ptlen);
    padlen = (16 - (ptlen % 16)) % 16;
    if (padlen) EVP_MAC_update(mctx, pad, padlen);
    unsigned char lens[16];
    uint64_t al = aadlen, cl = ptlen;
    for (int i = 0; i < 8; i++) lens[i] = (al >> (8*i)) & 0xff;
    for (int i = 0; i < 8; i++) lens[8+i] = (cl >> (8*i)) & 0xff;
    EVP_MAC_update(mctx, lens, 16);
    size_t taglen = 16;
    EVP_MAC_final(mctx, tag, &taglen, 16);
    EVP_MAC_CTX_free(mctx);
    EVP_MAC_free(mac);
    return 0;
}
EOF
