{"command":"cd /var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/algotuneprobe_jvvzz35p/ep0; cat > stream2.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
static size_t N; static unsigned char *a, *b; static int T;
static void* copy_worker(void* arg){
    long id=(long)arg; size_t chunk=N/T; size_t off=id*chunk; size_t sz=(id==T-1)?(N-off):chunk;
    memcpy(b+off, a+off, sz);
    return NULL;
}
static void* read_worker(void* arg){
    long id=(long)arg; size_t chunk=N/T; size_t off=id*chunk; size_t sz=(id==T-1)?(N-off):chunk;
    volatile unsigned long long s=0;
    unsigned long long *p=(unsigned long long*)(a+off);
    size_t cnt=sz/8;
    for(size_t i=0;i<cnt;i++) s += p[i];
    (void)s;
    return NULL;
}
int main(int argc,char**argv){
    T=atoi(argv[1]); N=512ull*1024*1024;
    a=malloc(N); b=malloc(N);
    memset(a,1,N); memset(b,2,N);
    pthread_t th[T];
    // warmup
    for(long i=0;i<T;i++) pthread_create(&th[i],NULL,copy_worker,(void*)i);
    for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    int iters=6;
    double t0=now();
    for(int it=0;it<iters;it++){
        for(long i=0;i<T;i++) pthread_create(&th[i],NULL,copy_worker,(void*)i);
        for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    }
    double t1=now();
    double bytes=(double)iters*2.0*N;
    printf("T=%d COPY: %.4f s -> r+w %.2f GB/s (copy %.2f GB/s)\n", T, t1-t0, bytes/(t1-t0)/1e9, bytes/2/(t1-t0)/1e9);
    t0=now();
    for(int it=0;it<iters;it++){
        for(long i=0;i<T;i++) pthread_create(&th[i],NULL,read_worker,(void*)i);
        for(long i=0;i<T;i++) pthread_join(th[i],NULL);
    }
    t1=now();
    bytes=(double)iters*N;
    printf("T=%d READ: %.4f s -> read %.2f GB/s\n", T, t1-t0, bytes/(t1-t0)/1e9);
    return 0;
}
