int main(){
    unsigned char key[32], nonce[12], zeros[64], block0[64];
    memset(key,0,32); memset(nonce,0,12); memset(zeros,0,64);
    unsigned char iv0[16]; memset(iv0,0,4); memcpy(iv0+4,nonce,12);

    // measure block0 in a loop
    double best=1e9;
    for(int it=0; it<100; it++){
        double a=now();
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv0);
        int outl=0;
        EVP_EncryptUpdate(ctx, block0, &outl, zeros, 64);
        EVP_CIPHER_CTX_free(ctx);
        double b=now();
        if(b-a<best) best=b-a;
    }
    printf("block0 best: %.4f ms\n", best*1000);

    // measure EVP_MAC_fetch in a loop
    best=1e9;
    for(int it=0; it<100; it++){
        double a=now();
        EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
        EVP_MAC_free(mac);
        double b=now();
        if(b-a<best) best=b-a;
    }
    printf("EVP_MAC_fetch best: %.4f ms\n", best*1000);

    // measure full poly1305 init+update+final (40MB)
    size_t n = 40*1024*1024;
    unsigned char *data = malloc(n);
    for(size_t i=0;i<n;i++) data[i]=i&0xff;
    unsigned char poly_key[32]; memset(poly_key,0,32);
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    OSSL_PARAM params[2];
    params[0]=OSSL_PARAM_construct_utf8_string(OSSL_MAC_PARAM_DIGEST,"POLY1305",0);
    params[1]=OSSL_PARAM_construct_end();
    unsigned char tag[16]; size_t taglen=16;
    best=1e9;
    for(int it=0; it<20; it++){
        EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
        EVP_MAC_init(mctx, poly_key, 32, params);
        double a=now();
        EVP_MAC_update(mctx, data, n);
        EVP_MAC_final(mctx, tag, &taglen, 16);
        double b=now();
        if(b-a<best) best=b-a;
        EVP_MAC_CTX_free(mctx);
    }
    printf("poly1305 update+final 40MB best: %.4f ms = %.2f GB/s\n", best*1000, n/best/1e9);

    // measure EVP_MAC_CTX_new + init
    best=1e9;
    for(int it=0; it<100; it++){
        double a=now();
        EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
        EVP_MAC_init(mctx, poly_key, 32, params);
        double b=now();
        if(b-a<best) best=b-a;
        EVP_MAC_CTX_free(mctx);
    }
    printf("EVP_MAC_CTX_new+init best: %.4f ms\n", best*1000);
    return 0;
}
